                            const axisRefX = idx === 1 ? 'x' : 'x' + idx;
                            const axisRefY = idx === 1 ? 'y' : 'y' + idx;
                            const axisKeyX = idx === 1 ? 'xaxis' : 'xaxis' + idx;
